//! Actual exact Element name payload and arena refusal, including no native slots.
use super::*;
#[test]
fn element_name_units_actual_record_payload_backing_no_slot_copy_refusal_and_recovery(){
 let mut doc=crate::html::parse("<html><body></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};let Value::Host(owner)=b.create_xml_document(MAIN_IMPLEMENTATION,&[Value::Null,Value::String(String::new())]).unwrap()else{panic!("owner")};b.state.node_limit=b.doc.nodes.len();let before=(b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.doc.nodes.len(),b.state.dom_commits);let limit=b.state.retained_limit;let copies=b.state.copy_work;let args=[Value::String(HTML_NAMESPACE.into()),Value::StringUnits(vec![0x70,0xd800,0x3a,0x41,0xdfff])];
 for storage in [true,false]{if storage{b.state.retained_limit=before.0;}else{b.state.copy_work=0;}assert!(b.create_expanded_element(owner,&args).is_err());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.doc.nodes.len(),b.state.dom_commits),before);b.state.retained_limit=limit;b.state.copy_work=copies;}
 let Value::Host(handle)=b.create_expanded_element(owner,&args).unwrap()else{panic!("exact source")};assert!(handle>=FIRST_ENTRY);assert_eq!(b.doc.nodes.len(),before.4);let record=b.state.inert_documents.node(handle).unwrap();assert_eq!(record.owner,owner);let Kind::Parsed{source:ParsedSource::Generated(source),..}=record.kind else{panic!("actual generated source")};let node=&b.state.inert_documents.generated[source].node;let NodeKind::Element{tag,expanded_name,href,..}=&node.kind else{panic!("element")};assert_eq!(tag,"A�");assert!(expanded_name[0].prefix.as_ref().unwrap().code_units().eq([0x70,0xd800]));assert!(expanded_name[0].local.as_ref().unwrap().code_units().eq([0x41,0xdfff]));let payload=node_bytes(node)+tag.capacity()+href.as_ref().map_or(0,String::capacity)+size_of::<Node>()+2*size_of::<usize>();assert_eq!(b.state.retained,before.0+payload+b.state.inert_documents.backing_bytes()-before.1);let Value::StringUnits(value)=b.inert_element_name_get(handle,"tagName").unwrap()else{panic!("actual units")};assert_eq!(value,[0x70,0xd800,0x3a,0x41,0xdfff]);
}
